/**
 * guestData.ts
 * Handles data for playing as a guest.
 * @version 2026.02.11
 */
export interface GuestTrack {
    track: {
        id: string;
        name: string;
        artists: { name: string }[];
        album: {
            name: string;
            images: { url: string }[];
        };
    };
    is_local?: boolean;
}

export interface GuestPlaylist {
    id: string;
    name: string;
    images: { url: string }[];
    tracks: { total: number };
    genres?: string[];
    decades?: string[];
}

